// 1. Recuperamos variables
const campaignId = $('create-campaign').first().json.id;
const optimizationGoal = "IMPRESSIONS";
const pageId = $('set-body-only').first().json.body.manualClientData.pageId;
const adAccountId = $('get-body').first().json.body.manualClientData.adAccountId;
const targetingData = $('split-adsets').first().json.targeting;
const adsetName = $input.first().json.name;

// 2. Construimos el body
let body = {
  name: adsetName,
  campaign_id: campaignId,
  status: "ACTIVE",
  billing_event: "IMPRESSIONS",
  optimization_goal: optimizationGoal,
  bid_strategy: "LOWEST_COST_WITHOUT_CAP",
  // ACTIVAMOS MODO DINÁMICO PARA MULTI-TEXTO
  is_dynamic_creative: false, 
  targeting: {
    age_min: targetingData.age_min,
    age_max: targetingData.age_max,
    geo_locations: {
      custom_locations: targetingData.custom_locations
    },
    excluded_geo_locations: {
      custom_locations: targetingData.excluded_custom_locations
    }
  }
};

// 3. Filtro de Promoted Object (Lógica Page ID)
const goalsWithoutPromotedObject = ['THRUPLAY', '2_SEC_VIDEO_VIEW', 'LINK_CLICKS', 'LANDING_PAGE_VIEWS'];

if (!goalsWithoutPromotedObject.includes(optimizationGoal)) {
  body.promoted_object = { "page_id": pageId };
}

return {
  json: {
    body: body,
    adAccountId: adAccountId
  }
};

// 1. Recuperamos variables
const campaignId = $('create-campaign').first().json.id;
const optimizationGoal = "IMPRESSIONS";
const pageId = $('set-body-only').first().json.body.manualClientData.pageId;
const adAccountId = $('get-body').first().json.body.manualClientData.adAccountId;
const currentItem = $input.first().json;
const targetingData = $('split-adsets').first().json.targeting;

// 2. Construimos el body
let body = {
  name: currentItem.name,
  campaign_id: campaignId,
  status: "ACTIVE",
  billing_event: "IMPRESSIONS",
  optimization_goal: optimizationGoal,
  bid_strategy: "LOWEST_COST_WITHOUT_CAP",
  // ACTIVAMOS MODO DINÁMICO PARA MULTI-TEXTO
  is_dynamic_creative: false,
  targeting: {
    age_min: targetingData.age_min,
    age_max: targetingData.age_max,
    geo_locations: {
      custom_locations: targetingData.custom_locations
    },
    excluded_geo_locations: {
      custom_locations: targetingData.excluded_custom_locations
    },
    flexible_spec: currentItem.targeting.flexible_spec.map(group => ({
      interests: group.interests.map(interest => ({
        id: interest.id,
        name: interest.name
      }))
    }))
  }
};

// 3. Filtro de Promoted Object
const goalsWithoutPromotedObject = ['THRUPLAY', '2_SEC_VIDEO_VIEW', 'LINK_CLICKS', 'LANDING_PAGE_VIEWS'];

if (!goalsWithoutPromotedObject.includes(optimizationGoal)) {
  body.promoted_object = { "page_id": pageId };
}

return {
  json: {
    body: body,
    adAccountId: adAccountId
  }
};

// 1. DATOS BASE
const pageId = String($('set-body-only').first().json.body.manualClientData.pageId);
const imageHash = String($('only-image-hash').first().json.hash); 
const adName = $('data-entry').first().json.referenceTitle ? String($('data-entry').first().json.referenceTitle) : "Ad Image Simple";

// 2. EXTRACCIÓN Y LIMPIEZA DEL COPY
// Usamos ?. para acceso seguro a la propiedad text
let rawCopy = $input.first().json.copy?.[0]?.text || null;

let copyText = "Ver más"; // Fallback inicial

if (rawCopy) {
  // Aseguramos que sea string y limpiamos
  let tempText = typeof rawCopy === 'string' ? rawCopy : JSON.stringify(rawCopy);

  copyText = tempText
    .replace(/\\n/g, '\n') // SOLUCIÓN: Convierte \\n literales en saltos reales
    .replace(/^"|"$/g, '') // Elimina comillas al inicio/final si el LLM las puso
    .trim();
}

// Validación final de seguridad por si quedó vacío después del trim
if (!copyText || copyText.length === 0) {
  copyText = "Ver más";
}

// 3. DATOS ADICIONALES
const title = String($('data-entry').first().json.title || "Título");
const description = String($('data-entry').first().json.description || "");
const ctaType = $('data-entry').first().json.cta || "LEARN_MORE";
const ctaUrl = String($('data-entry').first().json.ctaUrl);

// 4. CONSTRUCCIÓN FINAL DEL BODY (IMAGE STANDARD)
const finalBody = {
  name: adName,
  object_story_spec: {
    page_id: pageId,
    link_data: {
      image_hash: imageHash,
      link: ctaUrl,
      name: title,
      message: copyText, // ← COPY LIMPIO
      description: description,
      call_to_action: {
        type: ctaType,
        value: {
          link: ctaUrl
        }
      }
    }
  }
};

return { json: finalBody };

// 1. DATOS BASE
const pageId = String($('set-body-only').first().json.body.manualClientData.pageId);
const videoId = String($('Aggregate').first().json.data[0].id);
const thumbUrl = $('Aggregate').first().json.data[1].url;
const adName = $('data-entry').first().json.referenceTitle ? String($('data-entry').first().json.referenceTitle) : "Ad Video Simple";

// 2. EXTRACCIÓN Y LIMPIEZA DEL COPY
// Obtenemos el texto crudo. Usamos ?. para evitar errores si la estructura cambia
let rawCopy = $input.first().json.copy?.[0]?.text || null;

let copyText = "Ver más"; // Fallback por defecto

if (rawCopy && typeof rawCopy === 'string') {
  // CORRECCIÓN CRÍTICA:
  // Reemplazamos los saltos de linea literales (\\n) por saltos reales (\n)
  // Tambien limpiamos comillas dobles al inicio/final si el LLM las agregó
  copyText = rawCopy
    .replace(/\\n/g, '\n')  // Convierte \\n en salto real
    .replace(/^"|"$/g, '')  // Elimina comillas extra al principio o final si existen
    .trim();                // Elimina espacios en blanco sobrantes
} else {
  // Lógica de respaldo si n8n no lo trajo como string directo
   try {
       const parsed = typeof rawCopy === 'string' ? JSON.parse(rawCopy) : rawCopy;
       const extracted = parsed?.text || parsed?.copies?.[0]?.text;

       if (extracted) {
           copyText = String(extracted).replace(/\\n/g, '\n').trim();
       }
   } catch (e) {
       // Si todo falla, mantenemos el fallback o lo que se pueda rescatar
       if (rawCopy) copyText = String(rawCopy).trim();
   }
}

// 3. DATOS ADICIONALES
const title = String($('data-entry').first().json.title || "Título");
const description = String($('data-entry').first().json.description || "");
const ctaType = $('data-entry').first().json.cta || "LEARN_MORE";
const ctaUrl = String($('data-entry').first().json.ctaUrl);

// 4. CONSTRUCCIÓN FINAL DEL BODY
const finalBody = {
  name: adName,
  object_story_spec: {
    page_id: pageId,
    video_data: {
      video_id: videoId,
      image_url: thumbUrl,
      title: title,
      message: copyText, // ← Texto con saltos de línea corregidos
      link_description: description,
      call_to_action: {
        type: ctaType,
        value: {
          link: ctaUrl
        }
      }
    }
  }
};

return { json: finalBody };

// 1. Recuperamos variables
const campaignId = $('create-campaign1').first().json.id;
const adAccountId = $('get-body').first().json.body.manualClientData.adAccountId;

// Data del item actual (Targeting y Presupuesto)
const targetingData = $('split-adset').first().json.targeting;
const adsetName = $input.first().json.name;
const budgetAmount = $input.first().json.budget; // ABO: Presupuesto del conjunto

// 2. Construimos el body
let body = {
  name: adsetName,
  campaign_id: campaignId,
  status: "ACTIVE",

  // --- CAMBIOS CLAVE ---
  billing_event: "IMPRESSIONS",
  optimization_goal: "IMPRESSIONS", // Forzado para aceptar Multi-Copy
  daily_budget: budgetAmount,       // Configuración ABO
// is_dynamic_creative: true,        // Activado para aceptar los 3 copies
  bid_strategy: "LOWEST_COST_WITHOUT_CAP",
  // ---------------------

  targeting: {
    age_min: targetingData.age_min,
    age_max: targetingData.age_max,
    geo_locations: {
      custom_locations: targetingData.custom_locations
    },
    excluded_geo_locations: {
      custom_locations: targetingData.excluded_custom_locations
    }
  }
};

// NOTA IMPORTANTE:
// Al usar IMPRESSIONS para anuncios de contenido (Video/Imagen), 
// NO enviamos promoted_object (Page ID) aquí, o Facebook creerá que es una campaña de "Me Gusta".
// El Page ID ya va en el Ad Creative.

return {
  json: {
    body: body,
    adAccountId: adAccountId
  }
};

